begin;
set local role authenticated;select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
do $$
declare p uuid:='11111111-1111-4111-8111-111111111111';a jsonb;b jsonb;input jsonb;data_a jsonb;data_b jsonb;rev jsonb;run jsonb;op jsonb;hook_id uuid;token uuid:=gen_random_uuid();
begin
 input:='{"name":"Resource A","targetUrl":"http://localhost:3000/","allowedOrigins":["http://localhost:3000"],"viewport":{"width":1280,"height":720},"accountRole":"QA","requiredVariables":[],"startupInstructions":"Manual","targetVersion":"fixture","dataResourceKey":"shared-fixture"}'::jsonb;
 a:=public.save_dynamic_environment(p,input);b:=public.save_dynamic_environment(p,input||'{"name":"Resource B"}');
 begin perform public.record_dynamic_environment_data(p,(a->>'id')::uuid,'cleanup','completed','No preparation exists');raise exception 'Fresh cleanup created a reservation';exception when raise_exception then if sqlerrm='Fresh cleanup created a reservation' then raise;end if;end;
 data_a:=public.record_dynamic_environment_data(p,(a->>'id')::uuid,'preparation','completed','Prepared the shared fixture for A');
 if data_a->'resource'->>'reserved'<>'true' or data_a->'preparation'->>'resourceKey'<>'shared:shared-fixture' then raise exception 'Resource not frozen/reserved';end if;
 data_b:=public.read_dynamic_environment_data(p,(b->>'id')::uuid);if data_b->'resource'->>'available'<>'false' or data_b->'resource'->>'ownerName'<>'Resource A' then raise exception 'Peer did not see resource owner';end if;
 begin perform public.record_dynamic_environment_data(p,(b->>'id')::uuid,'preparation','completed','B must wait');raise exception 'B prepared reserved data';exception when raise_exception then if sqlerrm='B prepared reserved data' then raise;end if;end;
 begin perform public.save_dynamic_environment(p,a||'{"dataResourceKey":"relocated"}',(a->>'id')::uuid);raise exception 'Owner relocated reserved data';exception when raise_exception then if sqlerrm='Owner relocated reserved data' then raise;end if;end;
 begin perform public.acquire_dynamic_session_capture(p,(b->>'id')::uuid,'11111111-3333-4333-8333-111111111111','11111111-4444-4444-8444-111111111111','worker');raise exception 'B captured reserved data';exception when raise_exception then if sqlerrm='B captured reserved data' then raise;end if;end;
 rev:=public.save_dynamic_revision(p,auth.uid(),'{"name":"Reserved target","goal":"Observe form","targetUrl":"http://localhost:3000/","maxSteps":1,"context":null,"checks":[{"id":"one","criterionId":"one","description":"Form","kind":"visible_text","expected":"Ready","required":true}]}');
 begin perform public.start_dynamic_run(p,auth.uid(),(rev->>'id')::uuid,'no-profile-bypass');raise exception 'URL-only Run bypassed declared resource';exception when raise_exception then if sqlerrm='URL-only Run bypassed declared resource' then raise;end if;end;
 run:=public.start_dynamic_environment_run(p,auth.uid(),(rev->>'id')::uuid,'resource-a-run',a||'{"variableNames":[],"preflight":[{"name":"data","ready":true}]}');
 if run->'run'->'environment'->>'resourceKey'<>'shared:shared-fixture' then raise exception 'Run resource not frozen';end if;
 perform public.transition_dynamic_run(p,(run->'run'->>'id')::uuid,'queued','{"state":"cancelled","verdict":"not_tested","checks":[],"evidence":[]}'::jsonb);
 data_a:=public.record_dynamic_environment_data(p,(a->>'id')::uuid,'cleanup','failed','Seeded cleanup failure for A');if data_a->'resource'->>'reserved'<>'true' then raise exception 'Failed cleanup released resource';end if;
 begin perform public.start_dynamic_hook(p,(b->>'id')::uuid,'setup','b-during-dirty','{}');raise exception 'B hook used dirty resource';exception when raise_exception then if sqlerrm='B hook used dirty resource' then raise;end if;end;
 perform public.record_dynamic_environment_data(p,(a->>'id')::uuid,'cleanup','completed','Actual fixture cleanup verified for A');
 data_b:=public.record_dynamic_environment_data(p,(b->>'id')::uuid,'preparation','completed','Equivalent baseline prepared for B');if data_b->'resource'->>'reserved'<>'true' then raise exception 'B failed to reserve after cleanup';end if;
 perform public.record_dynamic_environment_data(p,(b->>'id')::uuid,'cleanup','completed','Withdraw B preparation without needing a Run');
 data_b:=public.read_dynamic_environment_data(p,(b->>'id')::uuid);if data_b->'resource'->>'reserved'<>'false' then raise exception 'Explicit release failed';end if;
 data_b:=public.record_dynamic_environment_data(p,(b->>'id')::uuid,'preparation','failed','Preparation partially failed; cleanup needed');if data_b->>'state'<>'cleanup_required' or data_b->'resource'->>'reserved'<>'true' then raise exception 'Failed preparation lost its dirty reservation';end if;
 perform public.record_dynamic_environment_data(p,(b->>'id')::uuid,'cleanup','completed','Recovered the partial preparation');
 op:=public.start_dynamic_hook(p,(a->>'id')::uuid,'setup','resource-hook-setup','{"program":"pnpm","script":"setup"}');hook_id:=(op->'operation'->>'id')::uuid;
 perform public.claim_dynamic_hook(p,hook_id,'resource-worker',token);perform public.finish_dynamic_hook(p,hook_id,token,'completed','{"outcome":"passed","exitCode":0}');
 if public.read_dynamic_environment_data(p,(a->>'id')::uuid)->'preparation'->>'resourceKey'<>'shared:shared-fixture' then raise exception 'Hook preparation omitted frozen resource';end if;
 op:=public.start_dynamic_hook(p,(a->>'id')::uuid,'cleanup','resource-hook-cleanup','{"program":"pnpm","script":"cleanup"}');hook_id:=(op->'operation'->>'id')::uuid;
 perform public.claim_dynamic_hook(p,hook_id,'resource-worker',token);perform public.finish_dynamic_hook(p,hook_id,token,'completed','{"outcome":"passed","exitCode":0}');
 perform public.record_dynamic_environment_data(p,(a->>'id')::uuid,'preparation','completed','New baseline after successful hook cleanup');
 if public.finish_dynamic_hook(p,hook_id,token,'completed','{"outcome":"passed","exitCode":0}') is not null or public.read_dynamic_environment_data(p,(a->>'id')::uuid)->'resource'->>'reserved'<>'true' then raise exception 'Old cleanup released a new reservation';end if;
 perform set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
 begin perform public.read_dynamic_environment_data(p,(a->>'id')::uuid);raise exception 'Nonmember read resource';exception when insufficient_privilege then null;end;
 raise notice 'PASS: shared ownership, snapshot freeze, preparation/capture/hook exclusion, URL-only bypass, cleanup failure, release and isolation';
end $$;
rollback;
